SET DEFINE OFF
SET SERVEROUTPUT ON
-- Dataset part 004 of 006. Run Script (F5) in numeric order, starting with 001.sql.
-- Run one dataset loader at a time. On any error, stop, fix it, then rerun from 001.sql.
-- Database-backed batch guards preserve order across separate Worksheet requests.
-- Complete loader SHA-256: 322e1b145d945b807fa28d5e6833687a342970232f4ff8e8cfa1d0e00de424d5
-- Contains attributed editorial summaries, not extracted source text.
DECLARE
  l_graph VARCHAR2(128); l_state VARCHAR2(16); l_hash VARCHAR2(64);
  l_old_hash VARCHAR2(64); l_existing CLOB; l_batch NUMBER; l_stage_count NUMBER;
BEGIN
  SELECT setting_value INTO l_graph FROM kcv_settings WHERE setting_key='DATASET_LOAD_GRAPH';
  SELECT state,graph_hash INTO l_state,l_hash FROM kcv_graph_runs WHERE graph_name=l_graph;
  IF l_hash<>'397da9d9f22e3188e89a7c6671d34e1edfef7528a6c106025a63e9a3a4f8b041' THEN RAISE_APPLICATION_ERROR(-20005,'Another dataset load replaced this run'); END IF;
  IF l_state<>'READY' THEN
    SELECT TO_NUMBER(setting_value) INTO l_batch FROM kcv_settings WHERE setting_key='DATASET_LOAD_BATCH';
    IF l_batch<>138 THEN RAISE_APPLICATION_ERROR(-20006,'Previous dataset batch failed; rerun the full loader'); END IF;
UPDATE kcv_settings SET setting_value='139' WHERE setting_key='DATASET_LOAD_BATCH';
DBMS_OUTPUT.PUT_LINE('Dataset batch 139/362 complete');
COMMIT;
END IF;
END;
/
